XXSNumleSolver::XXSNumleSolver() = default;

XXSNumleSolver::~XXSNumleSolver() = default;

XXSNumleSolver::XXSNumleSolver(int n)
{
    this->m_n = n;
}

void XXSNumleSolver::set_digit(int n)
{
    this->m_n = n;
}

void generate_permutations(int n, int current, std::string current_permutation,
                           std::unordered_set<char>& used_digits, std::unordered_set<std::string>& result)
{
    if (current == n)
    {
        result.insert(current_permutation);
        return;
    }
    for (int i = 0; i <= 9; ++i) {
        if (used_digits.find(i + '0') == used_digits.end())
        {
            used_digits.insert(i + '0');
            current_permutation.push_back(i + '0');
            generate_permutations(n, current + 1, current_permutation, used_digits, result);
            current_permutation.pop_back();
            used_digits.erase(i + '0');
        }
    }
}

