void XXSNumleSolver::init_set()
{
    this->m_guesses = XXSNumleSolver::get_permutations(this->m_n);
    this->m_set = this->m_guesses;

    this->m_pcm.clear();
    for(int i = 0; i <= this->m_n; i++)
    {
        for(int j = 0; j <= i; j++)
        {
            this->m_pcm.push_back({i, j});
        }
    }
}

bool XXSNumleSolver::is_valid_hint(const std::unordered_set<std::string> &set, 
                                   const std::string &guess, 
                                   int contained, 
                                   int matching)
{
    for (const auto& s : set) {
        if (XXSNumleChecker::contained(s, guess) == contained &&
            XXSNumleChecker::matching(s, guess) == matching) {
            return true;
        }
    }
    return false;
}

long double XXSNumleSolver::restrict(const std::string &guess, int contained, int matching)
{
    // 首先验证提示是否有效
    if (!is_valid_hint(this->m_set, guess, contained, matching)) {
        XXSConsole con;
        con.write("[WARN] 输入的提示与当前可能解集不相容，可能导致解集为空!").new_line();
    }
    
    long double p = XXSNumleSolver::calc_possibility(this->m_set, guess, contained, matching);
    long double info_content = 0.0;
    if(p > 0)
    {
        info_content = - std::log2l(p);
    }
    XXSNumleSolver::restrict_set(this->m_set, guess, contained, matching);
    this->m_history[guess] = {contained, matching};

    return info_content;
}

void XXSNumleSolver::restrict_set(std::unordered_set<std::string> &set,
                                  const std::string &guess, int contained, int matching)
{
    auto it = set.begin();
    while(it != set.end())
    {
        if( XXSNumleChecker::contained(*it, guess) != contained ||
            XXSNumleChecker::matching(*it, guess) != matching)
        {
            it = set.erase(it);
        }
        else
        {
            it++;
        }
    }
}

int XXSNumleSolver::get_set_size() const
{
    return this->m_set.size();
}

const std::unordered_set<std::string> &XXSNumleSolver::get_set() const
{
    return this->m_set;
}

long double XXSNumleSolver::calc_possibility(const std::unordered_set<std::string> &set,
                                             const std::string &guess, int contained,int matching)
{
    if (set.empty())
    {
        return 0.0;
    }
    size_t count = 0;
    for (const auto& s : set)
    {
        if (XXSNumleChecker::contained(s, guess) == contained &&
            XXSNumleChecker::matching(s, guess) == matching)
        {
            count++;
        }
    }
    return static_cast<long double>(count) / set.size();
}

long double XXSNumleSolver::calc_entropy(const std::unordered_set<std::string> &set,
                                         const std::vector<std::pair<int, int>> &pcm,
                                         const std::string &guess)
{
    long double entropy = 0.0;
    for(auto &p : pcm)
    {
        long double possibility = XXSNumleSolver::calc_possibility(set, guess, p.first, p.second);
        if(possibility > 0)
        {
            entropy += -(possibility * std::log2l(possibility));
        }
    }
    return entropy;
}

long double XXSNumleSolver::get_guess_entropy(const std::string &guess) const
{
    return XXSNumleSolver::calc_entropy(this->m_set, this->m_pcm, guess);
}

void entropy_worker(
    const std::unordered_set<std::string> *set,
    const std::vector<std::pair<int, int>> *pcm,
    const std::vector<std::string> *guesses,
    std::unordered_map<std::string, long double> *mge,
    std::mutex *mutex,
    std::atomic<int> *progress,
    bool b_show_progress,
    int total_guesses)
{
    // 创建GPU求解器实例
    static thread_local std::unique_ptr<::IGpuSolver> solver = ::GpuSolverFactory::createSolver();
    
    std::unordered_map<std::string, long double> local_mge;
    for (const auto& g : *guesses)
    {
        // 使用GPU求解器计算结果
        std::unordered_map<std::string, std::unordered_map<std::pair<int, int>, int, ::IGpuSolver::PairHash>> results;
        
        // 调用GPU求解器计算熵值
        bool success = solver->calculate_entropies(*set, {g}, *pcm, results);
        
        long double entropy = 0.0;
        if (success && results.find(g) != results.end()) {
            // 根据GPU计算结果计算熵值
            const auto& guess_results = results[g];
            size_t set_size = set->size();
            
            for (const auto& p : *pcm) {
                auto it = guess_results.find(p);
                if (it != guess_results.end()) {
                    long double possibility = static_cast<long double>(it->second) / set_size;
                    if (possibility > 0) {
                        entropy += -(possibility * std::log2l(possibility));
                    }
                }
            }
        } else {
            // 如果GPU计算失败，回退到CPU计算
            if (b_show_progress && solver->getBackendName() != "CPU") {
                XXSConsole con;
                con.write("[WARN] ").write(solver->getBackendName()).write(" 计算失败，回退到CPU计算").new_line();
            }
            entropy = XXSNumleSolver::calc_entropy(*set, *pcm, g);
        }
        
        local_mge[g] = entropy;

        // 移除处理进度的日志输出
        /* 
        if (b_show_progress)
        {
            int p = (*progress)++;
            if (p % 100 == 0) {  // 每100次才输出一次进度，减少日志量
                XXSConsole con;
                con.write("[INFO] 已处理 ").write(p).write(" 个猜测").new_line();
            }
        }
        */
    }

    std::lock_guard<std::mutex> lock(*mutex);
    mge->insert(local_mge.begin(), local_mge.end());
}

std::unordered_map<std::string, long double> XXSNumleSolver::calc_guess_entropy_map(
    const std::unordered_set<std::string> &set,
    const std::vector<std::pair<int, int>> &pcm,
    const std::unordered_set<std::string> &guesses,
    bool b_show_progress)
{
    std::unordered_map<std::string, long double> mge;
    std::mutex mutex;
    std::atomic<int> progress(0);
    int total_guesses = guesses.size();

    const int num_threads = std::thread::hardware_concurrency();
    std::vector<std::thread> threads;
    std::vector<std::vector<std::string>> thread_guesses(num_threads);

    // 将猜测均匀分配给线程
    int i = 0;
    for (const auto& g : guesses)
    {
        thread_guesses[i % num_threads].push_back(g);
        i++;
    }

    // 启动线程
    for (int t = 0; t < num_threads; ++t)
    {
        if (!thread_guesses[t].empty())
        {
            threads.emplace_back(entropy_worker, &set, &pcm, &thread_guesses[t], &mge, &mutex, &progress, b_show_progress, total_guesses);
        }
    }

    // 等待所有线程完成
    for (auto& t : threads)
    {
        t.join();
    }

    return mge;
}

std::pair<std::string, long double> XXSNumleSolver::find_best_guess(
    const std::unordered_set<std::string> &set,
    const std::vector<std::pair<int, int>> &pcm,
    const std::unordered_set<std::string> &guesses,
    bool b_show_progress)
{
    auto mge = XXSNumleSolver::calc_guess_entropy_map(set, pcm, guesses, b_show_progress);
    std::pair<std::string, long double> best_guess_entropy = {"Failed to find best guess", -1};
    for(auto &i : mge)
    {
        if(i.second > best_guess_entropy.second)
        {
            best_guess_entropy = i;
        }
    }
    return best_guess_entropy;
}

std::pair<std::string, long double> XXSNumleSolver::get_best_guess(bool b_show_progress) const
{
    if(this->m_M.count(this->m_history))
    {
        return this->m_M.at(this->m_history)[0];
    }
    return XXSNumleSolver::find_best_guess(this->m_set, this->m_pcm, this->m_guesses, b_show_progress);
}

const std::unordered_map<
    std::unordered_map<
        std::string,
        std::pair<int, int>>,
    std::vector<std::pair<
        std::string,
        long double>>,
    _xxs_tmp_hash1> &XXSNumleSolver::get_table() const
{
    return this->m_M;
}

void XXSNumleSolver::make_table(const std::string &filename)
{
    std::unordered_map<
        std::unordered_map<
            std::string,
            std::pair<int, int>>,
        std::vector<std::pair<
            std::string,
            long double>>,
        _xxs_tmp_hash1> M;

    std::queue<std::pair<std::unordered_map<
        std::string,
        std::pair<int, int>>,
        std::vector<std::pair<
            std::string,
            long double>>>> Q;

    std::string init_guess;
    for(int i = 0; i < this->m_n; i++)
    {
        init_guess.push_back(i + 1 + '0');
    }

    std::pair<
        std::unordered_map<
            std::string,
            std::pair<int, int>>,
        std::vector<std::pair<
            std::string,
            long double>>> init_element = {{}, {{init_guess, -1}}};

    M.insert(init_element);
    Q.push(init_element);

    while(!Q.empty())
    {
        auto p = Q.front();
        Q.pop();

        for(auto &cm : this->m_pcm)
        {
            auto mge = p.second;

            for(auto &ge : mge)
            {
                auto history = p.first;
                history[ge.first] = cm;

                std::unordered_set<std::string> restricted_set(this->m_set);
                for(auto &h : history)
                {
                    XXSNumleSolver::restrict_set(restricted_set, h.first, h.second.first, h.second.second);
                }

                if(restricted_set.size() <= 2)
                {
                    continue;
                }

                auto best = XXSNumleSolver::find_best_guess(restricted_set, this->m_pcm,
                                                            this->m_guesses, true);

                if(best.second > 0)
                {
                    if(M.find(history) == M.end())
                    {
                        M.insert({history, {best}});
                        Q.push({history, {best}});
                    }
                }
            }
        }
    }

    XXSConsole con;
    XXSFile file(filename);
    XXSStringHelper sh;
    for(auto &e : M)
    {
        sh.write("History ");
        for(auto &h : e.first)
        {
            sh.write("[ ").write(h.first).write(" ").write(h.second.first).write(" ");
            sh.write(h.second.second).write(" ]  ");
        }
        sh.write("     Numbers ");
        for(auto &ge : e.second)
        {
            sh.write("[ ").write(ge.first).write(" ").write(ge.second).write(" ]  ");
        }
        sh.new_line();
    }

    con.write(sh.str());
    file.set_data(sh.str());
    file.save();
}

void XXSNumleSolver::read_table(const std::string &filename)
{
    XXSFile file(filename);
    file.load();

    std::string data = file.get_data(), line;
    XXSStringHelper sh(data);
    while(sh.get_line(line))
    {
        if(line.empty())
        {
            continue;
        }

        XXSStringHelper lh(line);
        std::string str_label;
        lh.read(str_label);
        if(str_label != "History")
        {
            continue;
        }

        std::unordered_map<
            std::string,
            std::pair<int, int>> first;

        std::string str_fmt;
        for(lh.read(str_fmt); str_fmt == "[" && static_cast<bool>(lh); lh.read(str_fmt))
        {
            std::string num;
            int contained, matching;
            lh.read(num).read(contained).read(matching);
            first[num] = {contained, matching};
            lh.read(num); // == "]"
        }

        str_label = str_fmt;
        if(str_label != "Numbers")
        {
            continue;
        }

        std::vector<std::pair<
            std::string,
            long double>> second;

        for(lh.read(str_fmt); str_fmt == "[" && static_cast<bool>(lh); lh.read(str_fmt))
        {
            std::string guess;
            long double entropy;
            lh.read(guess).read(entropy);
            second.push_back({guess, entropy});
            lh.read(guess); // == "]"
        }

        this->m_M[first] = second;
    }
}